/*
 * Generated from public district boundaries of Maharashtra (2011 census).
 * Shapes are simplified for the home page branch map; the projection below
 * must stay in step with the paths. Do not edit by hand.
 */
export const MAP_W = 390;
export const MAP_H = 340;
const MIN_LNG = 74.13;
const MAX_LAT = 17.09;
const X_PER_DEG = 700.0;
const Y_PER_DEG = 733.0;

/** Position of a latitude/longitude on the 390 x 340 map canvas (may fall outside it). */
export function projectLatLng(lat: number, lng: number) {
  return { x: (lng - MIN_LNG) * X_PER_DEG, y: (MAX_LAT - lat) * Y_PER_DEG };
}

